import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-11-09

  const result = overdueInvoices([inv], '2026-11-08');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoice past due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-15

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2026-10-15');
  assert.equal(result[0].daysOverdue, 5);
});

test('overdueInvoices includes partially_paid invoice past due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPartial], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].daysOverdue, 5);
  assert.ok(result[0].due > 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = overdueInvoices([invResult.value], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPaid = recordPayment(invIssued, { amount: 48854, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPaid], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by most overdue first', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = overdueInvoices([inv2, inv1], '2026-10-25');
  assert.equal(result.length, 2);
  assert.equal(result[0].dueDate, '2026-10-15'); // More overdue
  assert.equal(result[1].dueDate, '2026-10-19'); // Less overdue
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[1].daysOverdue, 6);
});

test('overdueInvoices returns correct due amount for partially paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPartial], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 48854 - 10000);
});

test('overdueInvoices returns zero due for fully paid invoice before becoming overdue', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPaid = recordPayment(invIssued, { amount: 48854, date: '2026-10-10' }).value;

  // Paid invoices are excluded entirely
  const result = overdueInvoices([invPaid], '2026-10-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices on due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-15

  const result = overdueInvoices([inv], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices one day past due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-15

  const result = overdueInvoices([inv], '2026-10-16');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with multiple invoices, mixed status', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv3Result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;
  const inv3Result_draft = inv3Result.value; // Keep as draft
  const inv3Issued = issueInvoice(inv3Result.value, ['INV-2026-0001', 'INV-2026-0002']).value;
  const inv3Paid = recordPayment(inv3Issued, { amount: 48854, date: '2026-10-10' }).value;

  const result = overdueInvoices([inv1, inv2, inv3Result_draft, inv3Paid], '2026-10-25');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, 'INV-2026-0001'); // 10 days overdue
  assert.equal(result[1].number, 'INV-2026-0002'); // 6 days overdue
});

test('overdueInvoices with EOM terms', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-31

  const result = overdueInvoices([inv], '2026-11-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with NET30 terms', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-31

  const result = overdueInvoices([inv], '2026-11-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 15);
});

test('overdueInvoices includes all required fields', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 1);

  const item = result[0];
  assert.ok(item.number);
  assert.ok(item.customerId);
  assert.ok(item.dueDate);
  assert.ok(typeof item.daysOverdue === 'number');
  assert.ok(typeof item.due === 'number');
});

test('overdueInvoices with large number of invoices', () => {
  const invoices = [];
  for (let i = 0; i < 10; i++) {
    const invResult = createInvoice({
      customerId: `C-00${i + 1}`,
      issueDate: `2026-09-${String(i + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
      terms: 'NET14',
    });
    invoices.push(issueInvoice(invResult.value, invoices.map(inv => inv.number).filter(Boolean)).value);
  }

  const result = overdueInvoices(invoices, '2026-10-20');
  assert.equal(result.length, 10);
  // All should be overdue, sorted by most overdue first
  for (let i = 0; i < result.length - 1; i++) {
    assert.ok(result[i].daysOverdue >= result[i + 1].daysOverdue);
  }
});

test('overdueInvoices does not mutate input array', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  const invoices = [inv];
  const originalLength = invoices.length;

  overdueInvoices(invoices, '2026-10-20');

  assert.equal(invoices.length, originalLength);
});

test('overdueInvoices with early invoice and late invoice', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = overdueInvoices([inv1, inv2], '2026-10-30');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 31); // 2026-09-15 to 2026-10-30
  assert.equal(result[1].daysOverdue, 6); // 2026-10-24 to 2026-10-30
});

test('overdueInvoices handles negative daysOverdue in edge case', () => {
  // This shouldn't happen because we filter dueDate < asOf, but test for safety
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-11-03, asOf is 2026-10-30 (before due)

  const result = overdueInvoices([inv], '2026-10-30');
  assert.deepEqual(result, []);
});

test('overdueInvoices with same due date invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = overdueInvoices([inv1, inv2], '2026-10-20');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 5);
  assert.equal(result[1].daysOverdue, 5);
});

test('overdueInvoices across year boundary', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-12-29

  const result = overdueInvoices([inv], '2027-01-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 17);
});

test('overdueInvoices with partially paid high-value invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-008',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'BRAND-BOOK', qty: 3, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 2, discountPercent: 0 },
    ],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 500000, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPartial], '2026-10-20');
  assert.equal(result.length, 1);
  assert.ok(result[0].due > 0);
  assert.ok(result[0].due < 1000000); // Less than full amount
});

