  }).value, ['INV-2026-0001', 'INV-2026-0002']).value;
  const inv3Paid = recordPayment(inv3Issued, { amount: 48854, date: '2026-10-10' }).value;

  const result = overdueInvoices([inv1, inv2, inv3Draft, inv3Paid], '2026-10-25');
  assert.equal(result.length, 2);
